@extends('layouts.app') @section('title','Detalle de compra') @section('content')<div class="flex flex-wrap justify-between gap-4"><div><h1>Compra #{{ $purchase->id }}</h1><p class="mt-2 text-sm text-slate-500">{{ $purchase->supplier->name }} · {{ $purchase->created_at->format('d/m/Y H:i') }} · {{ $purchase->user->name }}</p></div><span class="badge self-start">{{ $purchase->status==='received'?'Recibida':'Pendiente de recepción' }}</span></div><div class="card overflow-hidden"><div class="overflow-x-auto"><table class="w-full"><thead><tr><th>Producto</th><th>Cantidad</th><th>Costo unitario</th><th>Descuento</th><th>Impuestos</th><th>Total</th></tr></thead><tbody>@foreach($purchase->items as $item)<tr><td>{{ $item->description }}</td><td>{{ $item->quantity }}</td><td>${{ $item->unit_price }}</td><td>${{ $item->discount }}</td><td>${{ $item->tax }}</td><td>${{ $item->total }}</td></tr>@endforeach</tbody></table></div><div class="space-y-2 border-t border-slate-100 p-6 text-right dark:border-slate-800"><p>Subtotal: ${{ $purchase->subtotal }}</p><p>Descuentos: ${{ $purchase->discount }}</p><p>Impuestos: ${{ $purchase->tax }}</p><p class="text-xl font-bold">Total: ${{ $purchase->total }}</p></div></div>@can('purchases.manage') @if($purchase->status==='draft')<form method="POST" action="{{ route('purchases.receive',$purchase) }}" onsubmit="return confirm('¿Confirmas que todos los productos fueron recibidos? Esta operación actualizará el inventario.')">@csrf<button class="btn">Confirmar recepción completa</button></form>@endif @endcan @endsection
